        {
            if(ctx->user_splt) continue; /* XXX: should check profile names for uniqueness */
            if(!chunk.length) return SPNG_ECHUNK_SIZE;

            ctx->file_splt = 1;

            if( !(ctx->stored & SPNG_CHUNK_SPLT) )
            {
